1	// Prework, executor-side (tasks-dispatch DESIGN §6.5, §14). The contract is
2	// unchanged from the slot mechanism — a subprocess with the task dir as cwd, the
3	// declared `required_secrets` as environment, a hard timeout, and the conditional
4	// `CLAUDINITE_REQUEST_AGENT` hand-off — so this module is a thin adapter that
5	// gives the queue's item identity where the slot id used to go, and adds the two
6	// things the queue states explicitly:
7	//
8	//  - RE-ENTRANCY IS THE REQUIREMENT, NOT IDEMPOTENCY (§6). A dead executor's
9	//    claim is reclaimed and the item re-picked, so prework can run again over its
10	//    own half-done work. That is convergence — check what exists, continue from
11	//    there — and it was always true of prework; the contract simply never said so.
12	//    Concurrent overlap with a zombie run is excluded by construction (the
13	//    executor job's timeout-minutes ≤ the executing leash), never asked of a task.
14	//  - A DECLARED SECRET THAT IS NOT CONFIGURED IS NAMED, NOT GUESSED AT (§14.7).
15	//    Prework is the only task code that ever sees a secret VALUE, so this is the
16	//    one place that can tell "unset" from "empty", and the item converges to
17	//    triage naming exactly which one is missing.
18	
19	import { runPrework, preworkFailure, agentRequestPath, clearAgentRequest, agentRequested, readAgentRequest } from '../prework.mjs';
20	
21	// The declared secrets this environment does not carry. An unset variable is
22	// missing; a set-but-empty one is the repo's own choice and is passed through.
23	export const missingSecrets = (names = [], env = process.env) =>
24	  names.filter((n) => env[n] === undefined);
25	
26	export function preworkRunner({ root, repo, defaultBranch, env = process.env }) {
27	  return async function runFor(task, { item, context = [] }) {
28	    const missing = missingSecrets(task.decl.required_secrets ?? [], env);
29	    if (missing.length) return { ok: true, agentRequested: false, missingSecrets: missing };
30	
31	    // The item's identity where the slot id used to be: the queue has no slot, and
32	    // the issue number IS the occurrence (§3). Workers read CLAUDINITE_ITEM.
33	    const requestPath = agentRequestPath({ pack: task.pack, task: task.id, slotId: `item-${item.number}` });
34	    clearAgentRequest(requestPath);
35	
36	    console.log(`::group::prework ${task.pack}/${task.id} [#${item.number}]`);
37	    const result = await runPrework(task.decl.prework, {
38	      taskDir: task.taskDir,
39	      env: {
40	        ...env,
41	        CLAUDINITE_REPO_ROOT: root,
42	        CLAUDINITE_REPO: repo,
43	        CLAUDINITE_DEFAULT_BRANCH: defaultBranch ?? '',
44	        CLAUDINITE_ITEM: String(item.number),
45	        CLAUDINITE_PACK: task.pack,
46	        CLAUDINITE_TASK: task.id,
47	        CLAUDINITE_CONTEXT: context.join('\n'),
48	        CLAUDINITE_REQUEST_AGENT: requestPath,
49	      },
50	      timeoutSeconds: task.decl.prework_timeout,
51	    });
52	    console.log('::endgroup::');
53	
54	    if (!result.ok) {
55	      clearAgentRequest(requestPath);
56	      const tail = result.stderr?.trim().split('\n').slice(-5).join('\n') ?? '';
57	      // Repeated OUTSIDE the group: Actions renders a group collapsed, so a failure
58	      // whose only evidence sits inside one still reads as unexplained.
59	      if (tail) console.log(tail);
60	      return { ok: false, why: preworkFailure(result), detail: tail };
61	    }
62	
63	    const requested = agentRequested(requestPath);
64	    const payload = requested ? readAgentRequest(requestPath) : null;
65	    clearAgentRequest(requestPath);
66	    return {
67	      ok: true,
68	      agentRequested: requested,
69	      delivered: deliveredLines(payload?.delivered),
70	      reason: payload?.reason ? (payload.reason.detail || payload.reason.code) : null,
71	    };
72	  };
73	}
