75	// What prework created, by identity — the agent's only source for those
76	// artifacts, and (absent an agent) what makes an outcome `delivered` rather than
77	// `done`. Absence is meaningful: a worker that created nothing writes no
78	// `delivered`, and the item then says nothing about artifacts rather than
79	// asserting something false.
80	export function deliveredLines(delivered) {
81	  const { branch = null, pr = null, merged = false } = delivered ?? {};
82	  const out = [];
83	  if (pr) out.push(`PR: #${pr}${merged ? ' (already merged — open your own PR for further work)' : ' (open)'}`);
84	  if (branch) out.push(`Branch: \`${branch}\``);
85	  return out;
86	}
